    [2199] = "Leve cinco barras de prata para Didiê Du Mocó em Altaforja.",
    [2200] = "Procure pistas sobre disposição atual do colar de Didiê dentro de Uldaman. O paladino morto que ele mencionou foi a última pessoa a portá-lo.",
    [2201] = "Encontre o rubi, a safira e o topázio que foram espalhados por toda Uldaman. Uma vez adquiridos, entre em contato com Didiê Du Mocó remotamente, usando o Frasco de Vidência que ele lhe deu.$B$BDe acordo com o diário...$B* O rubi está escondido em uma área barricada de Umbraforja.$B* O topázio está escondido numa urna em uma das áreas dos troggs, perto dos anões da Aliança.$B$B* A safira foi reivindicada por Grimlok, o líder dos troggs.",
    [2202] = "Leve 12 Campânulas de Fungo Magenta para Jarkal Limuno em Karrath.",
    [2204] = "Obtenha uma fonte de energia do constructo mais poderoso que você encontrar em Uldaman e entregue-a a Didiê Du Mocó em Altaforja.",
    [2240] = "Leia o Diário de Baelog, explore a câmara oculta, depois fale com o Prospector Lançatroz.",
    [2278] = "Fale com o vigia de pedra e descubra quais são os segredos da história antiga que ele guarda. Após aprender os segredos históricos, ative os Discos de Norgannon.",
    [2279] = "Leve a versão em miniatura dos Discos de Norgannon para a Liga dos Exploradores em Altaforja.",
    [2280] = "Leve a versão em miniatura dos Discos de Norgannon para algum dos sábios no Penhasco do Trovão.",
    [2283] = "Procure um colar valioso na escavação de Uldaman e leve-o para Dran Droffers em Orgrimmar. O colar pode estar danificado.",
    [2284] = "Encontre uma pista do paradeiro das gemas nas profundezas de Uldaman.",
    [2318] = "Encontre alguém que consiga traduzir o diário do paladino. O local mais próximo que pode ter alguém que o faça é Karrath, nos Ermos.",
    [2338] = "Empreste o colar a Jarkal. Em troca, ele vai traduzir o diário para você.",
    [2339] = "Recupere todas as três gemas e uma fonte de energia para o colar de Uldaman e leve-as para Jarkal Limuno, em Karrath. Jarkal acredita que uma fonte de energia pode ser encontrada no constructo mais forte presente em Uldaman.",
    [2340] = "Entregue o Colar e Gema Recuperados para Dran Droffers em Orgrimmar.",
    [2341] = "Visite Jarkal Limuno em Karrath para ver se ele obteve sucesso.",
    [2342] = "Pegue o tesouro de Patrício Garreta no baú de sua família, que está no Saguão Sul de Uldaman, e entregue a ele na Cidade Baixa.",
    [2359] = "Roube a chave, entre na Torre Défias e descubra o que tem dentro do Baú da Floresta do Crepúsculo. Leve todas as informações que coletar para Mathias Shaw em Ventobravo. Consulte o Diário de Marta se quiser mais detalhes sobre a torre.",
    [2360] = "Viaje para Cerro Oeste e encontre a Agente Marta Hari para receber instruções.",
    [2361] = "Eu lhe dou este colar com muita satisfação, imponente $C. Você me prestou um serviço inestimável e tem a minha gratidão por isso. Use-o com orgulho não deixe de sempre mencionar alto e em bom som quem o fez para você!$B$BAh, e se você puder dizer de passagem que ele não é amaldiçoado, seria ótimo também.",
    [2398] = "Encontre Baelog em Uldaman.",
    [2418] = "Leve 8 Pedras de Energia de Dêntrio e 8 Pedras de Energia de An'Alleum para Bertolezo nos Ermos.",
    [2439] = "Leve o vale-recompensa para Dinita Itamanto no Cofre de Altaforja.",
    [2440] = "Leve o vale-recompensa à Bena Casco Invernal no Penhasco do Trovão.",
    [2458] = "Vá à Torre da Empreendimentos S.A., ao norte do Charco de Lodo, e entre em contato com o agente secreto da Mão Despedaçada, o Capataz Arruela.$B$BQuando a torre estiver à vista, use o Sinalizador para anunciar sua chegada ao Capataz Arruela. Dispare DUAS vezes, depois aproxime-se do Capataz e faça a /continencia dos Mão Despedaçada.$B$BEstas ações devem ser executadas na ordem correta, já que Arruela vai atacar e eliminar qualquer pessoa que não reconheça.",
    [2460] = "Faça a Continência dos Mãos Despedaçada para Shenthul.",
    [2478] = "Roube a Chave da Torre do Capataz Biela e, em seguida, mate 2 Peões Mutantes da Empreendimentos S.A., 2 Patrulheiros da Empreendimentos S.A. e 2 Vigias da Empreendimentos S.A.$B$BArranque a cabeça do Capataz-chefe Gallywix, arrombe o cofre dele e roube o Esconderijo do Preparado Adulterado do Zanzil. Leve-o junto com a cabeça para Shenthul em Orgrimmar para receber mais instruções.",
    [2479] = "Vá até a Serraria Tarren, que fica no Contraforte de Eira dos Montes, e entregue a Amostra do Preparado de Zanzil a Serguei Hinoto.$B$BPara chegar à Serraria Tarren, pegue o Zepelim até a Cidade Baixa e siga a estrada em direção ao sul além de Pinhaprata, rumo à Eira dos Montes. É só seguir as placas!",
    [2480] = "Espere Serguei Hinoto concluir a cura.",
    [2607] = "Fale com o Doutor Mixilpixil no porão do Quartel.",
    [2608] = "Você precisa /deitar para ser $Gexaminado:examinada; pelo Doutor Mixilpixil. Como é que ele vai descobrir a cura se não puder identificar a causa do problema?",
    [2609] = "Leve para o Doutor Mixilpixil um pacote de Flores Silvestres Simples, uma Ampola Chumbada, um Tubo de Bronze e uma Bobina de Seda Chartreuse Leve. \"Ite\" nenhuma se cura sozinha, $Gmeu:minha; jovem.",
    [2621] = "Fale com o Comandante de Expedição Ruag em Pedregal.",
    [2622] = "Fale com Bengor.",
    [2623] = "Recupere as Ordens do Chefe Guerreiro e devolva-as ao Herói Caído da Horda.",
    [2681] = "Liberte nove Serviçais de Razelikh, três Serviçais de Sevine, três Serviçais de Allistarj e três Serviçais de Grol, depois fale novamente com o Herói Caído. Você precisa estar sempre próxim$GO:a; das pedras ou o processo fracassará.",
    [2701] = "Abra o baú e receba a sua recompensa.",
    [2702] = "Fale com o Cabo Thund Casco Fendido.",
    [2721] = "Descubra que fim levou o Tenente Kirith.",
    [2743] = "Fale novamente com o Herói Caído da Horda e conte suas descobertas.",
    [2744] = "Fale com Loramus Talípedes em Azshara.",
    [2745] = "Fale com Tyrion no Castelo Ventobravo.",
    [2746] = "Leve 3 Sedas e 2 Maçãs Frescas da Clara para Tyrion em Ventobravo.",
    [2768] = "Leve o Bastão Divinomático ao Engenheiro-chefe Silvadágua em Geringontzan.",
    [2770] = "Leve a Escama Eletrificada de Gahz'rilla para Capu Latafuso no Salar Cintilante.",
    [2783] = "Fale com o Herói Caído da Horda na fronteira entre Barreira do Inferno e o pântano.",
    [2784] = "Ouça o Herói Caído da Horda contando a história dele.",
    [2801] = "Ouça o Herói Caído da Horda contando a história dele.",
    [2846] = "Leve a Tiara das Profundezas para Tabetha no Pântano Vadeoso.",
    [2861] = "Fale com Tabetha no Pântano Vadeoso.",
    [2864] = "Fale com Tran'rek em Geringontzan.",
    [2865] = "Leve 5 Couraças de Escaravelho Fechadas para Tran'rek em Geringontzan.",
    [2936] = "Leia a Tabuleta de Theka para descobrir o nome da deusa aranha dos Cascasseca, depois fale novamente com o Mestre Gadrin.",
    [2983] = "Encontre Kranal Fiss nos Sertões.",
    [2984] = "Encontre Kranal Fiss nos Sertões.",
    [2985] = "Encontre Islen Vidente da Água nos Sertões.",
    [2986] = "Encontre Islen Vidente da Água nos Sertões.",
    [2991] = "Leve o Medalhão de Nekrum para Tádius Sombraustera na Barreira do Inferno.",
    [3001] = "Procure Strahad Farsan na Vila Catraca.",
    [3042] = "Leve 20 Frascos de Têmpera de Troll para Trenton Lumartelo em Geringontzan.",
    [3141] = "Ouça Loramus Talípedes contar sua história.",
    [3369] = "Leve a Lasca de Pesadelo para Hamuul Runa Totem no Platô dos Anciãos.",
    [3370] = "Leve a Lasca de Pesadelo para Mathrengyl Ursivagus em Darnassus.",
    [3373] = "Coloque a Essência de Erânicos na Fonte de Essência encontrada neste covil do Templo Submerso.",
    [3380] = "Encontre Marlon Catarrebite em Tanaris.",
    [3446] = "Encontre o Altar de Hakkar no Templo Submerso, que fica no Pântano das Mágoas.",
    [3447] = "Entre no Templo Submerso e descubra o segredo escondido no círculo de estátuas.",
    [3504] = "Entregue a Carta Lacrada para Ag'tor a Ag'tor Punho de Sangue, em Azshara.",
    [3505] = "Mate 10 Recuperadores Sanguinélficos e 10 Topógrafos Sanguinélficos antes de procurar o acampamento da Maga Rimtori. Quando localizá-lo, procure algo que possa ser importante para ela e possa ser usado para forçá-la a lutar.",
    [3508] = "Espere Loramus para completar o feitiço de iluminação.",
    [3509] = "Fale com o Lorde Arkkoroc em Azshara. comece sua busca na beira da água para encontrar o Templo de Arkkoran.",
    [3510] = "Mate Hetaera e leve a Cabeça Ensanguentada de Hetaera, a Cabeça Arrebentada de Hetaera e a Cabeça Ferida de Hetaera para o Lorde Arkkoroc.",
    [3511] = "Leve a têmpera para Loramus Talípedes.",
    [3520] = "Capture os espíritos de 3 guinchadores em Feralas, e depois fale novamente com Yeh'kinya no Porto de Bondebico.",
    [3527] = "Leve a Primeira e a Segunda Tabuleta Mosh'Aru para Yeh'kinya, em Tanaris.",
    [3528] = "Leve o Ovo de Hakkar Cheio para Yeh'kinya, em Tanaris.",
    [3602] = "Obtenha 20 Azsharitas Cristalizadas na região sul de Azshara. Use o Canisvil para farejar onde estão os depósitos que foram cuidadosamente escondidos.$B$BFale novamente com Loramus quando tiver cumprido essa tarefa.",
    [3621] = "Leve o Carregamento para Galvan, o Antigo, na Selva do Espinhaço.",
    [3625] = "Aguarde enquanto Galvan termina de forjar o armamento.",
    [3626] = "Fale novamente com o Herói Caído da Horda.",
    [3627] = "Mate Grol, o Destruidor, Lady Sevine e o Arquimago Allistarj. De seus corpos, pegue o Amuleto de Grol, o Amuleto de Sevine e o Amuleto de Allistarj.$B$BLembre-se de usar o Armamento Vil de Azsharita Encantada para enfraquecer a tríade, pois só assim eles podem ser derrotados... mas use-o com sabedoria.",
    [3628] = "Destrua Razelikh, o Profanador, e leve o Chifre Decepado de Profanador para o Herói Caído da Horda. Você também terá que devolver a Proteção do Profanador para que o Herói Caído a destrua, impedindo-a de cair em mãos erradas.",
    [3631] = "Fale com Strahad Farsan nos Sertões.",
    [3701] = "Vá até as Ruínas de Thaurissan, nas Estepes Ardentes, e descubra informações sobre as Relíquias de Thaurissan. Fale novamente com a Historiadora Real Arquefilis quando terminar.",
    [3702] = "Escute a Historiadora Real Arquefilis recontar a história de Thaurissan.",
    [3783] = "Colete 10 Peles Grossas de Yeti para Umi Zombarruga em Visteterna.",
    [3801] = "Fale com Franclorn Forjífice se tiver interesse em obter uma chave para a parte principal da cidade.",
    [3802] = "Mate Fineous Forçanegra e recupere o grande martelo Ferrovil. Leve-o para o Santuário de Thaurissan e coloque-o na estátua de Franclorn Forjífice.",
    [3844] = "Olhe em volta da lagoa para descobrir uma pista sobre quem pode ser o dono do bote destruído.",
    [3845] = "Examine os itens dentro da bolsa e leve até o dono.",
    [3903] = "Fale com Madel Quintana.",
    [3904] = "Leve 8 caixotes da Colheita da Madel para Madel Quintana na Abadia de Vila Norte.",
    [3907] = "Entre no Abismo Rocha Negra e encontre o Lorde Incendius. Mate-o e leve todas as informações que puder para o Coração Trovejante.",
    [3908] = "Leve a Espada de Linken para Bruna Covaneve em Hibérnia.",
    [3909] = "Procure Gregan Cospechope ao norte de Feralas. Descubra com ele como obter o elixir Videre, depois fale novamente com Bruna Covaneve em Hibérnia.",
    [3912] = "Vá até o cemitério perto de Geringontzan e use o Elixir Videre. Siga as outras instruções de Bruna para achar Gaeriyan.",
    [3913] = "Ressuscite, depois procure a lápida que Gaeriyan disse para você encontrar.",
    [3914] = "Leve a Espada Superior de Linken para Linken na Cratera Un'Goro.",
    [3941] = "Encontre J.D. Neri na caverna do Refúgio do Marshal.",
    [3942] = "Encontre Eridan Brisazul no sul da Selva Maleva.",
    [3961] = "Leve o Totem de Prata de Aquementas para Linken no Refúgio do Marshal.",
    [3962] = "Vá para o Pico Penacho de Fogo, ao sul do Refúgio do Marshal.$B$BEncontre Agni e use o totem para remover sua aura de proteção. Uma vez que for derrotado, pegue a Chama Dourada na caverna.",
    [3981] = "Encontre o Comandante Gor'shak no Abismo Rocha Negra.$B$BVocê se lembra que o tosco desenho incluía barras rabiscadas sobre o orc. Talvez você devesse procurar algum tipo de prisão.",
    [3982] = "Defenda Gor'shak.",
    [4001] = "Fale com Kharan Feromalho para obter informações sobre o sequestro da Princesa Moira Barbabronze. Leve as informações para Thrall em Orgrimmar.$B$BGor'shak mencionou que Kharan estava preso em uma cela próxima.",
    [4002] = "Fale com Thrall se estiver $Gpreparado:preparada; para assumir a missão que ele planejou.",
    [4003] = "Mate o Imperador Dagran Thaurissan e liberte a Princesa Moira Barbabronze do feitiço maligno.",
    [4004] = "Fale novamente com Thrall!",
    [4005] = "Leve o Livro de Aquor, as Garras Prateadas e o Coração de Ferrárbol até Tanaris.$B$BUse o Livro de Aquor para evocar Aquementas.$B$BApós ter completado o totem, leve-o para J.D. Neri no Refúgio do Marshal.",
    [4024] = "Vá para o Abismo Rocha Negra e mate Bael'gar.$B$BA única coisa que você sabe é que o gigante mora no Abismo Rocha Negra. Lembre-se de usar a Muda de Pele Alterada da Revoada Negra nos restos mortais de Bael'gar para capturar a Essência Abrasadora.$B$BLeve a Essência Abrasadora Aprisionada para Ciro Terepento.",
    [4063] = "Encontre e mate Lorde Golem Argelmach. Leve a cabeça dele para Lotwil. Você também precisará coletar 10 Núcleos de Elemental Intactos dos Golens Rasgafúria e Constructos Armipotentes que protegem Argelmach. Você sabe disso porque é paranormal.",
    [4081] = "Desbrave o Abismo Rocha Negra e destrua aqueles invasores degenerados!$B$BO Senhor da Guerra Trincador quer que você mate 15 Guardas Furiadastra, 10 Carcereiros Furiadastra e 5 Soldados Rasos Furiadastra. Fale novamente com ele quando o trabalho estiver terminado.",
    [4082] = "Vá até o Abismo Rocha Negra e destrua aqueles invasores degenerados!$B$BO Senhor da Guerra Trincador quer que você mate 10 Socorristas Furiadastra, 10 Soldados Furiadastra e 10 Oficiais Furiadastra. Fale novamente com ele quando o trabalho for concluído.",
    [4083] = "O cálice espectral flutua no ar, subindo e descendo lentamente... como se seguisse o bater de um coração agonizante.",
    [4084] = "Colete 11 Garras Prateadas e 1 Coração de Ferrárbol para Eridan Brisazul na Selva Maleva.",
    [4121] = "Escolte seu prisioneiro, Grark Lorkrub, pelas Estepes Ardentes, atravessando a Montanha Rocha Negra até chegar à Garganta Abrasadora.$B$BVocê se lembra de ter ouvido Lexlort dizer que mandaria seus homens esperar no outro lado para levar Grark sob custódia.$B$BVocê também vai precisar entregar os Grilhões de Tório para Lexlort.",
    [4122] = "Vá para as Estepes Ardentes e encontre Grark Lorkrub. Segundo Lexlort, ele foi visto pela última vez em uma imensa fortaleza Rocha Negra.$B$BQuando encontrar Grark Lorkrub, use os Grilhões de Tório para prendê-lo e levá-lo de volta à Garganta Abrasadora, passando pela Montanha Rocha Negra. Os homens de Lexlort estarão esperando do outro lado para levar Grark sob sua custódia.",
    [4123] = "Leve o Coração da Montanha para Maxwort Uberraio nas Estepes Ardentes.",
    [4124] = "Fale com Ginro Laracendis no Domínio de Plumaluna.",
    [4125] = "Encontre o barco do mensageiro em algum lugar da costa de Feralas.",
    [4126] = "Leve a Receita Perdida de Cervaforte para Ragnar Cervaforte em Kharanos.",
    [4127] = "Volte ao Domínio de Plumaluna e mostre a Faca Descartada que você achou a Ginro Laracendis.",
    [4128] = "Fale com Ragnar Cervaforte.",
    [4129] = "Leve a Faca Descartada para Quintis Jonespyre no Domínio de Plumaluna.",
    [4130] = "Fale com Ginro Laracendis no Domínio de Plumaluna.",
    [4131] = "Procure os acampamentos dos Gnolls Patábua ao sul de Feralas para obter pistas dos pertences do mensageiro ou dele próprio.",
    [4132] = "Viaje para o Abismo Rocha Negra e mate o General Forjaversa! Fale novamente com o Senhor da Guerra Trincador quando a tarefa estiver concluída.",
    [4133] = "Fale com a Mestra Sombria Vivian Latumba em Karrath.",
    [4134] = "Leve a Receita Perdida de Cervaforte para Vivian Latumba em Karrath.",
    [4135] = "Agora que o último paradeiro conhecido de Patiphe foi descoberto, continue sua busca por ele ou seus restos na Profundeza Atormentada. De acordo com o bilhete, ela fica ao sul dos acampamentos dos gnolls Patábua.",
    [4136] = "Leve a Cabeça do Ribas para Yuka Parafuseta nas Estepes Ardentes.",
    [4182] = "Mate 15 Filhotes Negros, 10 Dragomorfos Negros, 4 Draconoides Negros e 1 Draco Negro. Fale novamente com Helendis Flumicórnio quando a tarefa estiver concluída.",
    [4183] = "Viaje até Vila Plácida e entregue a Carta de Helendis Flumicórnio ao Magistrado Salomão.",
    [4184] = "Viaje para Ventobravo e entregue o Apelo de Salomão ao Grão-lorde Bolvar Fordragon.$B$BBolvar reside na Bastilha Ventobravo.",
    [4185] = "Fale com o Grão-lorde Bolvar Fordragon depois de falar com a Lady Katrana Prestor.",
    [4186] = "Leve o Decreto de Bolvar para o Magistrado Salomão, em Vila Plácida.",
    [4201] = "Leve 4 Sangues-de-grom, 10 Veios de Prata Gigantes e a Ampola da Nagmara Cheia para a Lady Nagmara no Abismo Rocha Negra.",
    [4223] = "Fale com o Oficial Maxwell nas Estepes Ardentes.",
    [4224] = "Fale com João Roto para saber o destino do Marechal Vilasboas e fale novamente com o Oficial Maxwell quando tiver completado essa tarefa.$B$BVocê se lembra do Oficial Maxwell lhe dizendo para procurá-lo em uma caverna ao norte.",
    [4241] = "Viaje para a Montanha Rocha Negra, a noroeste, e entre no Abismo Rocha Negra. Descubra o que aconteceu com o Marechal Vilasboas.$B$BVocê se lembra de João Roto falando sobre Vilasboas ter sido arrastado para uma prisão.",
    [4242] = "Leve as más notícias ao Oficial Maxwell.",
    [4263] = "Encontre Lorde Incendius no Abismo Rocha Negra e destrua-o!",
    [4264] = "Você pode ter acabado de descobrir algo que o Marechal Vilasboas estaria interessado em ver. Pode haver esperança, afinal.",
    [4265] = "Liberte Patiphe da colmeia de Zukk'ash.$B$BAvise a Ginro Laracendis no Domínio de Plumaluna que Patiphe está são e salvo.",
    [4266] = "Fale com Shandris Plumaluna no Domínio de Plumaluna.",
    [4267] = "Leve o Relatório do Patiphe para Gracinha Forçânima em Darnassus.",
    [4281] = "Leve o Pacote Extraviado para Falfindel Trilhemas em Thalanaar.",
    [4282] = "Recupere as Informações Perdidas do Marechal Vilasboas.$B$BO Marechal Vilasboas acredita que as informações estão sendo mantidas pelo Lorde Golem Argelmach e pelo General Forjaversa.",
    [4286] = "Viaje para o Abismo Rocha Negra e recupere 20 Pochetes Ferro Negro. Fale novamente com Oralius quando tiver completado a tarefa. Você supõe que os anões Ferro Negro de dentro do Abismo Rocha Negra carregam essa tal de \"pochete\".",
    [4322] = "Ajude o Marechal Vilasboas a recuperar seu equipamento e libertar seus amigos. Se conseguir, fale novamente com o Oficial Maxwell.",
    [4324] = "Fale com Yuka Parafuseta nas Estepes Ardentes.",
    [4341] = "Viaje para Abismo Rocha Negra e encontre Kharan Feromalho.$B$BO Rei mencionou que Kharan estava preso lá — talvez seja bom procurar uma prisão.",
    [4342] = "Ouça Kharan Feromalho contar a história dele.",
    [4361] = "Volte a Altaforja e dê as más notícias ao Rei Magni Barbabronze.",
    [4362] = "Volte ao Abismo Rocha Negra e resgate a Princesa Moira Barbabronze das garras malignas do Imperador Dagran Thaurissan.",
    [4363] = "Volte a Altaforja e fale com o Rei Magni Barbabronze.",
    [4487] = "Fale com Strahad Farsan na Vila Catraca.",
    [4488] = "Fale com Strahad Farsan na Vila Catraca.",
    [4489] = "Fale com Strahad Farsan na Vila Catraca.",
    [4490] = "Fale com Strahad Farsan, na Vila Catraca, para aprender a habilidade de evocar um Corcel Vil.",
    [4701] = "Vá ao Pico da Rocha Negra e destrua a fonte da ameaça worg. Quando você deixou Helendis, ele gritou um nome: Halycon. É assim que os orcs se referem aos worgs.",
    [4724] = "Mate Halycon, senhora da matilha dos Worgs Machado Sangrento.",
    [4729] = "Vá para o Pico da Rocha Negra e encontre Filhotes de Worg Machado Sangrento. Use a jaula para carregar essas pequenas feras. Leve um Filhote de Worg Enjaulado para Kibler.",
    [4734] = "Use o Protótipo de Ovosciloscópio em um ovo no Viveiro.",
    [4735] = "Leve 8 Ovos de Dragão Recolhidos e o Módulo Colectrônico a Vera Brequim no Monte Candente, que fica nas Estepes Ardentes.",
    [4742] = "Encontre as três gemas da autoridade: a Gema de Espinho Fúmeo, a Gema de Agulhapétrea e a Gema de Machado Sangrento. Entregue-as, junto com o Selo da Ascensão sem Adorno, a Vaelan.$B$BOs generais, como informado a você por Vaelan, são: Senhor da Guerra Voone dos Fumocardo, Grão-lorde Omokk dos Agulhapétrea e Lorde Supremo Wyrmthalak dos Machado Sangrento.",
    [4743] = "Vá para o Pântano da Serpe, que fica no Pântano Vadeoso. Encontre o draco ancião Ardeluta e ataque-o sem misericórdia até que sua vontade seja quebrada.$B$BÉ nesse momento que você deve colocar o Selo da Ascensão de Metal Bruto em frente a essa fera imponente. Você deve então ser $Grápido:rápida; para usar o Orbe de Energia Dracônica em sua forma enfraquecida e dominar suas faculdades mentais. Controle a fera e lance as chamas da Revoada Dragônica Negra sobre o Selo da Ascensão de Metal Bruto!",
    [4764] = "Leve o Broche do Finitudo para Mayara Asaluz nas Estepes Ardentes.",
    [4765] = "Leve a Caixote de Espargosa para o Conde Capistrano de Espargosa em Ventobravo.",
    [4766] = "Fale com Mayara Asaluz nas Estepes Ardentes.",
    [4768] = "Leve a Tabuleta de Pedranegra à Umbramante Vivian Latumba, em Karrath.",
    [4769] = "Fale com a Umbramante Vivian Latumba.",
    [4771] = "Coloque a Aposta da Aurora na Sala de Exibição de Scolomântia. Derrote Vectus, depois fale novamente com Betina Bigozinco.",
    [4787] = "Leve o Ovo Velho para Yeh'kinya, em Tanaris.",
    [4788] = "Leve a Quinta e a Sexta Tabuletas Mosh'Aru ao Prospector Botaférrea, em Tanaris.",
    [4862] = "Vá para o Pico da Rocha Negra e colete 15 Ovos de Aranha do Pináculo para Kibler.$B$BPelo nome, é de se pensar que eles fiquem perto das aranhas.",
    [4866] = "No coração do Pico da Rocha Negra você vai encontrar a Mãe Queimateia. Chame a atenção dela e deixe-a envenenar você. É bem provável que você precise matá-la também. Fale novamente com João Roto depois que for envenenad$Go:a; para que ele possa \"ordenhar\" você.",
    [4867] = "Leia o Pergaminho do Warosh. Traga o Mojo do Warosh para Warosh.",
    [4903] = "Mate o Grão-lorde Omokk, o Senhor da Guerra Voone e o Lorde Supremo Wyrmthalak. Recupere Documentos Importantes dos Rocha Negra. Fale novamente com o Senhor da Guerra Trincador, em Karrath, quanto a missão tiver sido cumprida.",
    [4907] = "Fale com Vera Brequim.",
    [4921] = "Encontre a Mulher de Mankrik e depois fale novamente com ele na Encruzilhada.",
    [4941] = "Fale com Eitrigg em Orgrimmar. Quando tiver discutido o assunto com Eitrigg, busque o conselho de Thrall.$B$BVocê se lembra de ter visto Eitrigg nos aposentos de Thrall.",
    [4974] = "Viaje para o Pico da Rocha Negra e mate o Chefe Guerreiro Laceral Mão Negra. Pegue sua cabeça e volte para Orgrimmar.",
    [4981] = "Vá ao Pico da Rocha Negra e descubra o que aconteceu com Biju.",
    [4982] = "Encontre os Pertences de Biju e devolva-os a ela. Ela mencionou tê-los guardado no nível mais profundo da cidade.",
    [4983] = "Leve o Relatório de Reconhecimento de Biju para o Grão-mestre Lexlort em Karrath.",
    [5001] = "Encontre os Pertences de Biju e devolva-os a ela. Boa sorte!",
    [5002] = "Viaje para as Estepes Ardentes e dê as Informações de Biju para o Oficial Maxwell.",
    [5047] = "Fale com Málifus Trevamalho em Visteterna.",
    [5061] = "Volte a Darnassus e mostre a Mathrengyl Ursivagus o Pingente do Leão Marinho.",
    [5065] = "Leve a Terceira e a Quarta Tabuletas Mosh'Aru ao Prospector Botaférrea, em Tanaris.",
    [5081] = "Vá para o Pico da Rocha Negra e mate o Senhor da Guerra Voone, o Grão-lorde Omokk e o Lorde Supremo Wyrmthalak. Fale novamente com o Oficial Maxwell quando terminar o trabalho.",
    [5089] = "Leve o Comando do General Drakkisath para o Oficial Maxwell nas Estepes Ardentes.",
    [5096] = "Vá até a base de operações da Cruzada Escarlate, que fica entre o Campo Pedravil e as Lágrimas de Dalson, e destrua a Tenda de Comando.$B$BPlante a bandeira do Flagelo no acampamento e fale novamente com o Alto-executor Arcabuz no Baluarte, nas Terras Pestilentas Ocidentais.",
    [5097] = "Usando a Tocha Sinalizadora, marque cada torre em Andorhal. Você tem que ficar na entrada da torre para conseguir marcá-la.$B$BDepois de marcar as quatro torres, leve a Tocha Sinalizadora de volta para o Comandante Ashlam Punhobom no Acampamento Ventogelante, que fica nas Terras Pestilentas Ocidentais.",
    [5098] = "Usando a Tocha Sinalizadora, marque cada torre em Andorhal. Você tem que ficar na entrada da torre para conseguir marcá-la.$B$BDepois de marcar as quatro torres, leve a Tocha Sinalizadora de volta para o Alto-executor Arcabuz no Baluarte, nas Terras Pestilentas Ocidentais.",
    [5102] = "Viaje de volta ao Pico da Rocha Negra e destrua o General Drakkisath. Depois, fale novamente com o Oficial Maxwell.",
    [5122] = "Requirements:$B- Medalhão da Fé",
    [5125] = "$N, estou morrendo... mas minha alma está salva. Não tenho nem palavras para dizer o quanto devo a você. Por favor, leve isto consigo. Continue lutando, valente $C!",
    [5127] = "Viaje para o Pico da Rocha Negra e encontre Goraluk Rachadastra. Mate-o e use o Pique Manchado de Sangue no cadáver dele. Quando a alma dele tiver sido canalizada, o pique ficará Manchado de Almas.$B$BVocê também precisa encontrar o Peitoral Rúnico de Metal Bruto.$B$BLeve o Pique Manchado de Almas e o Peitoral Rúnico de Metal Bruto para Vegax, em Hibérnia.",
    [5142] = "Encontre Pâmela Trilharrubra.",
    [5149] = "Encontre a boneca de Pâmela.",
    [5152] = "Fale com Marlene, ao sul das Ruínas de Andorhal.",
    [5153] = "Leve o Anel de Casamento do Josefo para Crona.",
    [5154] = "Leve os Anais da Vila das Flechas para Crona em Andorhal.",
    [5160] = "Viaje para Hibérnia e encontre Haleh. Entregue para ela a Escama do Albi.",
    [5163] = "Leve o Yeti Mecânico da Umi e assuste os amigos dela:$B$BLegacki, em Visteterna (Hibérnia),$BSguisha, em Geringontzan (Tanaris) e$BQuixxil, no Refúgio do Marshal (Cratera Un'Goro).$B$BQuando terminar, leve o Yeti Mecânico de volta para Umi.",
    [5168] = "Leve o Incunábulo de Davil e o Escudo de Trilharrubra para Carlin Trilharrubra.",
    [5181] = "Leve o Crânio de Horgus e a Espada Estilhaçada de Marduk para Carlin Trilharrubra na Capela Esperança da Luz.",
    [5206] = "Leve 5 Crânios Ressonantes e o Cristal Místico para Carlin Trilharrubra nas Terras Pestilentas Orientais.",
    [5210] = "Leve os Anais Estendidos da Vila das Flechas para Carlin Trilharrubra nas Terras Pestilentas Orientais.",
    [5211] = "Liberte 15 Espíritos da Vila das Flechas e fale novamente com Carlin Trilharrubra.",
    [5212] = "Recupere 20 Amostras de Carne Infectada de Stratholme e leve-as para Betina Bigozinco. Você desconfia que qualquer criatura em Stratholme poderia ter essa amostra de carne.",
    [5213] = "Vá para Stratholme e vasculhe os zigurates. Encontre novos Dados do Flagelo e leve-os para Betina Bigozinco.",
    [5214] = "Encontre a tabacaria de Ezra Carranca em Stratholme e recolha uma caixa do Tabaco da Lata do Carranca. Fale novamente com Leandro Leonardo depois que tiver terminado o serviço.",
    [5241] = "Encontre Carlin Trilharrubra.",
    [5243] = "Viaje para Stratholme, ao norte. Procure os caixotes de suprimentos que cobrem a cidade e recupere 5 Águas Bentas de Stratholme. Fale novamente com Leonid Bartolomeu, o Venerado, quando coletar fluido abençoado suficiente.",
    [5251] = "Viaje até Stratholme e encontre o Arquivista Galford da Cruzada Escarlate. Destrua-o e queime o Arquivo Escarlate.",
    [5262] = "Leve a Cabeça do Balnazzar para o Duque Nicolau Zverenhoff nas Terras Pestilentas Orientais.",
    [5263] = "Desbrave Stratholme e destrua o Barão Rivendare. Corte sua cabeça e leve-a de volta para o Duque Nicolau Zverenhoff.",
    [5282] = "Use o Canhão de Ectoplasma do Egan nos moradores fantasmagóricos e espectrais de Stratholme. Depois de livrá-los da forma de fantasma, use o canhão de novo e BLAU: liberdade!$B$BLiberte 15 Almas Inquietas, depois fale novamente com Egan.",
    [5341] = "Desbrave Scolomântia e recupere a fortuna da família Barov. A fortuna é composta por quatro escrituras: A Escritura de Castro das Flechas, A Escritura de Montalvo, A Escritura da Serraria Tarren e A Escritura de Costa Sul. Fale novamente com Alexei Barov quando tiver terminado a tarefa.",
    [5342] = "Vá para o Acampamento Ventogelante, no território da Aliança, e assassine Weldon Barov. Recolha a cabeça dele e fale novamente com Alexei Barov.$B$BEsteja avisad$Go:a;: Weldon provavelmente estará muito bem protegido pela escória da Aliança.",
    [5343] = "Desbrave Scolomântia e recupere a fortuna da família Barov. A fortuna é composta por quatro escrituras: A Escritura de Castro das Flechas, a Escritura de Montalvo, a Escritura da Serraria Tarren e a Escritura de Costa Sul. Fale novamente com Weldon Barov quando tiver terminado a tarefa.",
    [5344] = "Vá para o Baluarte, no território da Horda, e assassine Alexei Barov. Recolha a cabeça dele e fale novamente com Weldon Barov.$B$BEsteja avisad$Go:a;: Alexei provavelmente estará muito bem protegido pela escória da Horda.",
    [5382] = "Encontre o Doutor Theolen Krastinov em Scolomântia. Destrua-o, depois queime os Restos Mortais de Eva Sarkhoff e os Restos Mortais de Lucien Sarkhoff. Fale novamente com Eva Sarkhoff depois que tiver terminado a tarefa.",
    [5383] = "Leve o Saco de Horrores para Eva Sarkhoff, em Castro das Flechas.",
    [5384] = "Volte a Scolomântia com o Sangue dos Inocentes em mãos. Encontre a varanda e derrame o Sangue dos Inocentes no braseiro. Kirtonos virá na intenção de devorar sua alma.$B$BLute com bravura, não dê nenhuma brecha! Destrua Kirtonos e fale novamente com Eva Sarkhoff.",
    [5461] = "Viaje para o Planalto Arathi, até as ruínas de Stromgarde. Vasculhe Stromgarde em busca de um Livro de Recordações. Se encontrar o item, retorne com ele até o Magistrado Marduque.",
    [5462] = "Viaje para a Capela Esperança da Luz, nas Terras Pestilentas Orientais, e procure por Leonid Bartolomeu, o Venerado. Mostre a ele o Livro de Recordações e conte tudo o que descobriu.",
    [5463] = "Vá até Stratholme e encontre a Dádiva de Menethil. Ponha o Livro de Recordações no solo profanado.",
    [5464] = "Leve a Lembrança Vinculada para Leonid Bartolomeu, nas Terras Pestilentas Orientais.",
    [5465] = "Fale novamente com o Magistrado Marduque, no Castro das Flechas. Mostre-lhe a Lembrança Vinculada.",
    [5466] = "Procure por Ras Friomúrmuro em Scolomântia. Quando o encontrar, use a Lembrança Vinculada em sua versão morto-vivo. Quando conseguir transformá-lo novamente em mortal, mate-o e recupere a Cabeça Humana de Ras Friomúrmuro. Leve a cabeça de volta ao Magistrado Marduque.",
    [5514] = "Leve os Fragmentos de Ossos Imbuídos e 15 moedas de ouro para Rugov A. Massoaço em Geringontzan.",
    [5515] = "Localize Janice Barov em Scolomântia e a destrua. Recupere o Saco de Horrores de Krastinov do cadáver dela. Entregue o saco a Eva Sarkhoff.",
    [5518] = "Leve 4 Peças de Runatrama, 8 Couros Rústicos, 2 Fios Rúnicos e Tanino Ôgrico para Fiapo Agulhacerta. Atualmente, ele está acorrentado dentro da ala Gordok do Gládio Cruel.",
    [5525] = "É chamada de chave dos grilhões dos Gordok. Bom, pelo menos é esse o nome que essas coisinhas fofas usam. Acho que qualquer um dos ogros pode ter a sua, mas é mais provável que os guardas tenham um exemplar...$B$BPeraí, onde é que eu estou com a cabeça? Já está com você, não é mesmo? Está aqui?",
    [5528] = "Como você é o dono do pedaço agora, vai provar de graça as minhas melhores cervejas! Elas levantam até defunto... e vão deixar você pra lá de Terralém! Essas são papa-fina mesmo, chefia. Dá uma provadinha e diga pro Kreeg o que você acha!",
    [5529] = "Mate 20 Filhotes Pestilentos, depois fale novamente com Betina Bigozinco, na Capela Esperança da Luz.",
    [5531] = "Leve os Ovos Congelados para Betina Bigozinco.",
    [5533] = "Fale com o Alquimista Arvignon no Morro do Ventogelante, que fica nas Terras Pestilentas Ocidentais.",
    [5537] = "Leve 15 Fragmentos de Ossos para o Alquimista Arvignon no Morro do Ventogelante, que fica nas Terras Pestilentas Ocidentais.",
    [5538] = "Leve os Fragmentos de Ossos Imbuídos e 15 moedas de ouro para Rugov A. Massoaço em Geringontzan.",
    [5582] = "Leve a Escama de Dragão Saudável para Betina Bigozinco na Capela Esperança da Luz, que fica nas Terras Pestilentas Orientais.",
    [5601] = "Encontre Pâmela Trilharrubra na Vila das Flechas.",
    [5721] = "Coloque o Saco de Relíquias na praça da Vila das Flechas.$B$BImpeça que Davil Luminoso morra antes de Horgus.$B$BImpeça que o Capitão Trilharrubra morra antes que Trilharrubra, o Corrompido, surja.$B$BDerrote Trilharrubra, o Corrompido.$B$BFale com o espírito de Josefo Trilharrubra quando ele aparecer na praça, depois fale com Pâmela na casa dela.",
    [5742] = "Escute o que Tirion Fordring tem a dizer.",
    [5762] = "Leve o Caixote de Kravel para Rosarães Guima na Selva do Espinhaço.",
    [5763] = "Leve o Chifre de Kodo de Roon para Rosarães Guima na Selva do Espinhaço.",
    [5781] = "Viaje para a Chácara Secreta, no extremo sul das Terras Pestilentas Orientais, e recupere o Martelo de Taelan. Fale novamente com Tirion Fordring ao completar seu objetivo.",
    [5801] = "Leve o Molde de Chave-mestra e 2 Barras de Tório para o topo do Pico Penacho de Fogo, na Cratera Un'Goro. Use o Molde de Chave-mestra no lago de lava para forjar a Chave-mestra Inacabada.$B$BLeve a Chave-mestra Inacabada para o Alquimista Arvignon no Morro do Ventogelante, que fica nas Terras Pestilentas Ocidentais.",
    [5802] = "Leve o Molde de Chave-mestra e 2 Barras de Tório para o topo do Pico Penacho de Fogo, na Cratera Un'Goro. Use o Molde de Chave-mestra no lago de lava para forjar a Chave-mestra Inacabada.$B$BLeve a Chave-mestra Inacabada para o Boticário Trépido no Baluarte, que fica nas Terras Pestilentas Ocidentais.",
    [5803] = "Destrua Araj, o Evocador e leve o Escaravelho de Araj para o Alquimista Arvignon no Morro do Ventogelante, que fica nas Terras Pestilentas Ocidentais.",
    [5804] = "Destrua Araj, o Evocador e leve o Escaravelho de Araj para o Boticário Trépido no Baluarte, que fica nas Terras Pestilentas Ocidentais.",
    [5845] = "Viaje para o Vilarejo do Norte, na região nordeste das Terras Pestilentas Orientais, e recupere o Símbolo da Honra Perdida. Fale novamente com Tirion Fordring ao completar seu objetivo.",
    [5846] = "Viaje para a ilha de Castro das Flechas, na região centro-sul das Terras Pestilentas, e procure pistas sobre o paradeiro da pintura.",
    [5848] = "Viaje para Stratholme, na parte norte das Terras Pestilentas. No Bastião Escarlate, você encontrará a pintura \"Do Amor e da Família\", escondida atrás de outro quadro que retrata as luas gêmeas do nosso mundo.$B$BLeve a pintura de volta para Tirion Fordring.",
    [5861] = "Viaje para a Tumba de Uther, que fica nas Terras Pestilentas meridionais. Mostre a Dádiva de Tirion para Myranda, a Bruxa Velha.",
    [5862] = "Fale com Myranda para receber a Ilusão Escarlate. Viaje para Amparo sob o efeito de Ilusão Escarlate e entregue a Dádiva de Tirion para o Grão-lorde Taelan Fordring.$B$BAmparo fica ao norte e Taelan estará dentro da Bastilha Mardenforte.",
    [5921] = "Use o feitiço \"Teleporte: Clareira da Lua\" para viajar para a Clareira da Lua. Ao chegar, fale com Dendrite Stellardor, no vilarejo de Refúgio Noturno.",
    [5922] = "Use o feitiço \"Teleporte: Clareira da Lua\" para viajar para a Clareira da Lua. Ao chegar, fale com Dendrite Stellardor, no vilarejo de Refúgio Noturno.",
    [5923] = "Fale com Mathrengyl Ursivagus no Enclave Cenariano, em Darnassus.",
    [5924] = "Fale com Mathrengyl Ursivagus no Enclave Cenariano, em Darnassus.",
    [5925] = "Fale com Mathrengyl Ursivagus no Enclave Cenariano, em Darnassus.",
    [5926] = "Fale com Turak Runa Totem no Platô dos Anciãos, que fica no Penhasco do Trovão.",
    [5927] = "Fale com Turak Runa Totem no Platô dos Anciãos, que fica no Penhasco do Trovão.",
    [5928] = "Fale com Turak Runa Totem no Platô dos Anciãos, que fica no Penhasco do Trovão.",
    [5929] = "Procure o Espírito do Grande Urso na região noroeste da Clareira da Lua e aprenda o que ele tem a compartilhar com você sobre a natureza do urso. Quando terminar, fale novamente com Dendrite Stellardor no Refúgio Noturno, que fica na Clareira da Lua.",
    [5930] = "Procure o Espírito do Grande Urso na região noroeste da Clareira da Lua e aprenda o que ele tem a compartilhar com você sobre a natureza do urso. Quando terminar, fale novamente com Dendrite Stellardor no Refúgio Noturno, que fica na Clareira da Lua.",
    [5931] = "Volte a Darnassus e fale com Mathrengyl Ursivagus no Enclave Cenariano.",
    [5932] = "Volte ao Penhasco do Trovão e fale com Turak Runa Totem no Platô dos Anciãos.",
    [5941] = "Leve a Coleção de Relíquias para Crona em Andorhal.",
    [5942] = "Leve a Chave de Josefo ao Baú de Josefo.",
    [5944] = "Escolte Taelan Fordring para fora de Amparo.",
    [6001] = "Aplique Poeira de Lua Cenariana na Pedra Luniscante de Auberdine para trazer Lunagarra. Então, enfrente Lunagarra e ganhe a força de corpo e coração que ele possui.$B$BFale com Mathrengyl Ursivagus em Darnassus quando você terminar.",
    [6002] = "Aplique Poeira Lunar Cenariana na Pedra Luniscante entre Mulgore e os Sertões para evocar Lunagarra. Então, enfrente Lunagarra e ganhe a força de corpo e coração que ele possui.$B$BFale com Turak Runa Totem no Penhasco do Trovão quando terminar.",
    [6004] = "Mate 2 Socorristas Escarlate, 2 Caçadores Escarlate, 2 Magos Escarlate e 2 Cavaleiros Escarlate antes de voltar a Kirsta Sombrafunda, nas Terras Pestilentas Ocidentais.",
    [6023] = "Mate o Guarda-caça Eiras e o Fidalgo Durgen antes de voltar à Kirsta Sombrafunda, nas Terras Pestilentas Ocidentais.",
    [6025] = "Entre em Amparo e encontre um lugar alto de onde possa ver a cidade e avaliar as forças da Cruzada Escarlate. Então fale novamente com Kirsta Sombrafunda nas Terras Pestilentas Ocidentais.",
    [6061] = "Use o Bastão de Adestramento para domar um Pinote Adulto. Pratique sua habilidade e depois devolva o Bastão de Adestramento a Yaw Crina Cortante na Aldeia Casco Sangrento.",
    [6062] = "Use o Bastão de Adestramento para domar uma Mosquetusco Hediondo. Pratique sua habilidade e depois devolva o Bastão de Adestramento a Thotar no Monte Navalha.",
    [6063] = "Use o Bastão de Adestramento para domar uma Tocaieira Lenhateia. Pratique sua habilidade e depois devolva o Bastão de Adestramento a Dazalar em Dolanaar.",
    [6064] = "Use o Bastão de Adestramento para domar uma Rochetusco Grande. Pratique sua habilidade e depois devolva o Bastão de Adestramento a Grif Selvacuore em Kharanos.",
    [6065] = "Fale com Yaw Crina Cortante na Aldeia Casco Sangrento.",
    [6066] = "Fale com Yaw Crina Cortante na Aldeia Casco Sangrento.",
    [6067] = "Fale com Yaw Crina Cortante na Aldeia Casco Sangrento.",
    [6068] = "Fale com Thotar no Monte Navalha.",
    [6069] = "Fale com Thotar no Monte Navalha.",
    [6070] = "Fale com Thotar no Monte Navalha.",
    [6071] = "Fale com Dazalar em Dolanaar.",
    [6072] = "Fale com Dazalar em Dolanaar.",
    [6073] = "Fale com Dazalar em Dolanaar.",
