    [6081] = "Fale com Ormak Tiroatroz em Orgrimmar.",
    [6082] = "Use o Bastão de Adestramento para domar um Escorpídeo Encouraçado. Pratique sua habilidade e depois fale novamente com Thotar no Monte Navalha.",
    [6083] = "Use o Bastão de Adestramento para domar uma Surfatisco. Pratique sua habilidade e depois devolva o Bastão de Adestramento a Thotar no Monte Navalha.",
    [6084] = "Use o Bastão de Adestramento para domar uma Leopardo da Neve. Pratique sua habilidade e depois fale novamente com Grif Selvacuore em Kharanos.",
    [6085] = "Use o Bastão de Adestramento para domar um Urso Garra de Gelo. Pratique sua habilidade e depois devolva o Bastão de Adestramento a Grif Selvacuore em Kharanos.",
    [6086] = "Fale com Bélia Granitrondo em Altaforja.",
    [6087] = "Use o Bastão de Adestramento para domar um Espreitador-da-pradaria. Pratique sua habilidade e depois devolva o Bastão a Yaw Crina Cortante na Aldeia Casco Sangrento.",
    [6088] = "Use o Bastão de Adestramento para domar uma Rapineiro. Pratique sua habilidade e depois devolva o Bastão a Yaw Crina Cortante na Aldeia Casco Sangrento.",
    [6089] = "Fale com Holto Chifre Troante no Platô dos Caçadores, que fica no Penhasco do Trovão.",
    [6101] = "Use o Bastão de Adestramento para domar um Espreitador Sabre-da-noite. Treine sua perícia, e depois devolva o Bastão de Adestramento a Dazalar em Dolanaar.",
    [6102] = "Use o Bastão de Adestramento para domar uma Guinchadora Estrígida. Treine sua perícia, e depois devolva o Bastão de Adestramento a Dazalar em Dolanaar.",
    [6103] = "Fale com Jocasta no Enclave Cenariano, que fica em Darnassus.",
    [6121] = "Vá à Clareira da Lua e fale com Dendrite Stellardor no vilarejo de Refúgio Noturno.",
    [6122] = "Use o Coletor Vazio das Quedas de Fontescarpa para coletar uma amostra de água da entrada da caverna da cachoeira.$B$BEntregue o Coletor Cheio das Quedas de Fontescarpa para Alanndária Noturcanto em Auberdine, na Costa Negra.",
    [6123] = "Leve 5 Raízes-telúricas e 12 Fungos Lunares para Alanndária Noturcanto em Auberdine para que ela possa preparar o bálsamo curativo.",
    [6124] = "Use o Bálsamo Curativo para Animais em 10 Cervos Adoentados espalhados pela Costa Negra. Isso deve curá-los. Cervos Adoentados foram avistados da região ao sul do Rio Fontescarpa, seguindo até a área ao norte de Auberdine, até a Costa Negra meridional, na fronteira do Vale Gris.",
    [6125] = "Fale novamente com Mathrengyl Ursivagus no Enclave Cenariano, em Darnassus.",
    [6126] = "Vá à Clareira da Lua e fale com Dendrite Stellardor no vilarejo de Refúgio Noturno.",
    [6127] = "Use o Coletor Vazio do Morro de Brumedo para obter uma amostra de água de um lago no topo do morro.$B$BEntregue o Coletor Cheio do Morro de Brumedo a Tonga Runa Totem na Encruzilhada, nos Sertões.",
    [6128] = "Leve 5 Raízes-telúricas e 5 Chifres de Kodo para Tonga Runa Totem na Encruzilhada para que ele possa preparar um bálsamo curativo.",
    [6129] = "Use o Bálsamo Curativo para Animais em 10 Gazelas Doentes espalhadas pelo norte dos Sertões. Isso deve curá-las. Gazelas Doentes foram avistadas por toda parte a norte da estrada leste-oeste, que atravessa a Encruzilhada.",
    [6130] = "Fale novamente com Turak Runa Totem no Platô dos Anciãos, no Penhasco do Trovão.",
    [6141] = "Fale com o Irmão Anton na Desolação.",
    [6144] = "Vá à Cidade Baixa e fale com Varimatras.",
    [6145] = "Volte às Terras Pestilentas Orientais e rastreie o Mensageiro Carmesim. Mate o mensageiro e obtenha as Ordens do Grão-cruzado.$B$BLeve-as para Nathanos Arauto da Praga para obter suas próximas instruções.",
    [6146] = "Vá à Manopla de Tyr, a sudeste do Sítio dos Marris. Quando chegar lá, coma um pedaço da Maçã Podre. Com o disfarce da Cruzada Escarlate, entregue as Ordens do Grão-cruzado ao Lorde Cruzado Valdelmar.",
    [6147] = "Fale novamente com Nathanos Arauto da Praga para repassar a ele as novas informações.",
    [6148] = "A Cruzada Escarlate está em marcha. Em algum ponto da estrada da Manopla de Tyr para Stratholme estará o Oráculo, Demétria, e a comitiva dela. Encontre-a e mate-a. Fale novamente com Nathanos Arauto da Praga se tiver sucesso.",
    [6163] = "Vá a Stratholme e mate Ramstein, o Devorador. Leve a cabeça dele como souvenir para Nathanos.",
    [6402] = "Viaje a Ventobravo e vá até os portões da cidade. Fale com o Escudeiro Rui para que ele avise ao Marechal Vilasboas que você chegou.",
    [6403] = "Siga Reginaldo Vilasboas através de Ventobravo. Proteja-o de qualquer ataque!",
    [6501] = "Você deve vasculhar o mundo em busca de uma criatura capaz de restaurar o poder do Fragmento do Olho do dragão. A única informação que você tem sobre essa criatura é que ela existe.",
    [6502] = "Você precisa obter o Sangue do Campeão dos Dragões Negros do General Drakkisath.",
    [6566] = "Ouça Thrall.",
    [6567] = "Procure Rexxar. O Chefe Guerreiro $Go:a; instruiu quanto ao paradeiro dele. Procure nos caminhos de Desolação, entre a Cordilheira das Torres de Pedra e Feralas.",
    [6568] = "Leve o Testamento de Rexxar para Myranda, a Bruxa Velha, nas Terras Pestilentas Ocidentais.",
    [6569] = "Vá para o Pico da Rocha Negra e colete 20 Olhos de Dragomorfo Preto. Fale novamente com Myranda, a Bruxa Velha, depois que tiver terminado a tarefa.",
    [6570] = "Vá até o Pântano da Serpe, no Pântano Vadeoso, e procure o Covil de Ardeluta. Quando estiver lá, use o Amuleto de Subversão Dracônica e fale com Ardeluta.",
    [6582] = "Encontre e mate o Áugure, o draco da Revoada Dragônica Azul. Arranque a cabeça do draco morto e leve-a para Ardeluta.$B$BVocê sabe que o Áugure se encontra em Hibérnia.",
    [6583] = "Destrua Somnus, o draco campeão da Revoada Verde. Pegue seu crânio e leve-o para Ardeluta.",
    [6584] = "Guardando as Cavernas do Tempo no Deserto de Tanaris, encontra-se Chronalis, filho de Nozdormu. Destrua-o e leve seu crânio para Ardeluta.",
    [6585] = "Vá para Grim Batol e encontre Axtroz, o draco campeão da Revoada Vermelha. Destrua-o e arranque sua cabeça. Leve o crânio para Ardeluta.",
    [6601] = "Pelo jeito, a farsa chegou ao fim. Você já sabe que o Amuleto de Subversão Dracônica criado por Myranda, a Bruxa Velha, não vai funcionar no Pico da Rocha Negra. Você devia ir atrás de Rexxar e explicar a situação. Mostre a ele o Amuleto da Chama Dracônica Fraco. Pode ser que ele saiba o que fazer.",
    [6602] = "Viaje para o Pico da Rocha Negra e mate o General Drakkisath. Recolha seu sangue e leve-o para Rexxar.",
    [6681] = "Leve o Selo de Corvoforte para Fahrad na Mansão de Corvoforte, que fica oculta nas colinas de Eira dos Montes.$B$BSua jornada testará sua sagacidade. Prepare-se.",
    [6721] = "Fale com Dazalar em Dolanaar.",
    [6722] = "Fale com Dazalar em Dolanaar.",
    [6981] = "Viaje para a Vila Catraca e procure alguém que possa contar mais alguma coisa sobre a lasca faiscante.$B$BDepois, entregue a lasca conforme as orientações.",
    [7028] = "Colete 25 Entalhes de Cristal Terádrico para Faia, na Desolação.",
    [7029] = "Encha a Ampola Cerúlea Tampada na poça de cristal laranja, em Maraudon.$B$BUse a Ampola Cerúlea Cheia nos Cipós Caule Torpe para forçar os Rebentos Tóxxicos corrompidos a emergir.$B$BCure 8 plantas ao matar os Rebentos Tóxxicos, depois fale novamente com Vark Chaga de Guerra, na Aldeia Pescassombra.",
    [7041] = "Encha a Ampola Cerúlea Tampada na poça de cristal laranja, em Maraudon.$B$BUse a Ampola Cerúlea Cheia nos Cipós Caule Torpe para forçar os Rebentos Tóxxicos corrompidos a emergir.$B$BCure 8 plantas ao matar os Rebentos Tóxxicos, depois fale novamente com Talendria, no Posto do Nijel.",
    [7044] = "Recupere as duas partes do Cetro de Celebras: o Bastão de Celebras e o Diamante de Celebras.$B$BEncontre um jeito de falar com Celebras.",
    [7046] = "Ajude Celebras, o Redimido, a criar o Cetro de Celebras.$B$BFale com ele quando o ritual estiver concluído.",
    [7064] = "Mate a Princesa Theradras e fale novamente com Selendra perto da Aldeia Pescassombra, na Desolação.",
    [7065] = "Mate a Princesa Theradras e fale novamente com o Guardião Marandis no Posto do Nijel, na Desolação.",
    [7066] = "Procure Remulos, na Clareira da Lua, e entregue a ele a Semente da Vida.",
    [7067] = "Leia as Instruções do Pária. Depois, obtenha em Maraudon o Amuleto da União e devolva-o ao Centauro Pária, na parte sul de Desolação.",
    [7068] = "Colete 10 Fragmentos de Lascanegra em Maraudon e leve-os para Uthel'nay, em Orgrimmar.",
    [7070] = "Colete 10 Fragmentos de Lascanegra em Maraudon e leve-os para o Arquimago Tervosh, em Theramore, na costa do Pântano Vadeoso.",
    [7201] = "Vá até o Abismo Rocha Negra e obtenha 10 Essências dos Elementos. Seu primeiro impulso é procurar nos golens e criadores de golens. Você lembra que Vivian Latumba também mencionou elementais.",
    [7441] = "Vá ao Gládio Cruel e encontre o Diabrete Pusillin. Convença-o usando qualquer meio que for necessário a lhe dar o Livro de Encantamentos de Azj'Tordin.$B$BFale novamente com Azj'Tordin no Pavilhão Lariss, em Feralas, caso você recupere o Livro de Encantamentos.",
    [7461] = "Mate os guardiões que cercam os cinco pilares de força da Prisão de Immol'thar. Quando os pilares se desligarem, o campo de força que cerca Immol'thar se dissipará.$B$BDestrua o terrível demônio que fica no coração da Prisão de Immol'thar. Por fim, enfrente o Príncipe Tortheldrin, no Ateneu.$B$BFale novamente com a Anciã Shen'dralar, no pátio, após cumprir a missão.",
    [7462] = "Volte ao Ateneu e encontre o Tesouro dos Shen'dralar. Reclame sua recompensa!",
    [7463] = "Vá ao Distrito Lenhatorta, no Gládio Cruel, e mate o elemental da água, Rebentágua. Leve a Essência de Rebentágua para o Erudito Lydros, no Ateneu.",
    [7481] = "Procure Telmius Romanesca no Gládio Cruel. Reporte-se, então, ao Sábio Korolusk na Aldeia Mojache com qualquer informação que você encontrar.",
    [7482] = "Procure Telmius Romanesca no Gládio Cruel. Reporte-se, então, à Erudita Runacardos em Plumaluna com qualquer informação que você encontrar.",
    [7488] = "Leve a Teia de Letendris para Latrônicus Lunalança no Domínio de Plumaluna, em Feralas.",
    [7489] = "Leve a Teia de Letendris para Talo Casco de Espinhos na Aldeia Mojache, em Feralas.",
    [7490] = "Leve a Cabeça da Onyxia para Thrall em Orgrimmar.",
    [7491] = "Procure o Lorde Supremo Runthak no Vale da Força.",
    [7492] = "Fale com Talo Casco de Espinhos na Aldeia Mojache, em Feralas.",
    [7493] = "$GUm matador:Uma matadora; de dragões e $Gum coureiro experiente:uma coureira experiente;? Você não para de me surpreender, $Gherói:heroína;. Sinto-me honrado.$B$BPor favor, aceite o que estou prestes a lhe ensinar. Esse conhecimento será inestimável se você pretende destruir o que resta da Revoada Negra.$B$BConfeccione o manto com as escamas da mãe da ninhada. Ele protegerá você e seus aliados do sopro incendiário do Senhor da Rocha Negra... Nefarian.",
    [7494] = "Fale com Latrônicus Lunalança no Domínio de Plumaluna, em Feralas.",
    [7495] = "Leve a Cabeça da Onyxia ao Grão-lorde Bolvar Fordragon em Ventobravo.",
    [7496] = "Procure o Major Valadão no Vale dos Heróis.",
    [7497] = "$GUm matador:Uma matadora; de dragões e $Gum coureiro experiente:uma coureira experiente;? Você não para de me surpreender, $Gherói:heroína;. Sinto-me honrado.$B$BPor favor, aceite o que estou prestes a lhe ensinar. Esse conhecimento será inestimável se você pretende destruir o que resta da Revoada Negra.$B$BConfeccione o manto com as escamas da mãe da ninhada. Ele protegerá você e seus aliados do sopro incendiário do Senhor da Rocha Negra... Nefarian.",
    [7498] = "Devolva o livro aos legítimos donos.",
    [7499] = "Devolva o livro aos legítimos donos.",
    [7500] = "Devolva o livro aos legítimos donos.",
    [7501] = "Devolva o livro aos legítimos donos.",
    [7502] = "Devolva o livro aos legítimos donos.",
    [7503] = "Devolva o livro aos legítimos donos.",
    [7504] = "Devolva o livro aos legítimos donos.",
    [7505] = "Devolva o livro aos legítimos donos.",
    [7506] = "Devolva o livro aos legítimos donos.",
    [7507] = "Leve o Compêndio do Abate de Dragões de Nostro até o Ateneu.",
    [7508] = "Dê a Lâmina Élfica Lisa e Cega ao Erudito Lydros.",
    [7509] = "Faça Onyxia soprar fogo na Lâmina Ancestral Virgem. Quando conseguir, pegue a agora Lâmina Ancestral Incandescente. Atenção, uma Lâmina Ancestral Incandescente não permanecerá assim para sempre — o tempo urge.$B$BO último passo antes de voltar para mim é matar a fera e enfiar a Lâmina Ancestral Incandescente no cadáver dela.$B$BFaça isso e Quel'Serrar será sua.",
    [7562] = "Fale com Mor'zul Trazangre nas Estepes Ardentes.",
    [7563] = "Leve 30 garrafas de Sangue de Fera em Fúria para Mor'zul Trazangre nas Estepes Ardentes.",
    [7564] = "Leve o Caixote de Sangue para Gorzeeki Olholouco nas Estepes Ardentes.",
    [7604] = "Entregue o Contrato da Irmandade do Tório para Lokhtos Umbrarganha, caso tenha interesse em receber as instruções para Sulfuron.",
    [7623] = "Compre Poções Sombrias de Gorzeeki nas Estepes Ardentes.$B$BUse as poções para viajar através de Jaedenar e fale com Lorde Nihilus.",
    [7624] = "Confronte Ulathek, depois leve o Coração do Traidor para o Lorde Nihilus em Jaedenar.",
    [7625] = "Compre Poeira Estelar Zorothiana de Ur'dan. Leve-a para Gorzeeki Olholouco nas Estepes Ardentes.",
    [7626] = "Leve 10 Elixires de Poder Sombrio para Gorzeeki Olholouco nas Estepes Ardentes.",
    [7627] = "Leve 6 Estilhaços Brilhantes Grandes e 25 Minérios de Ferro Negro para Gorzeeki nas Estepes Ardentes.",
    [7628] = "Leve 35 Escamas de Dragão Negro para Gorzeeki Olholouco nas Estepes Ardentes.",
    [7629] = "Leve o Diabrete numa Jarra para o laboratório de alquimia em Scolomântia. Depois que o pergaminho for criado, devolva a jarra para Gorzeeki Olholouco.",
    [7630] = "Leve 3 Barras de Arcanita para Gorzeeki nas Estepes Ardentes.",
    [7631] = "Leia as Instruções de Mor'zul. Evoque um Corcel Medonho Zorothiano, derrote-o e então vincule o espírito dele a você.",
    [7632] = "Encontre o dono da Folha Antiga Petrificada. Boa sorte, $N, pois o mundo é grande.",
    [7634] = "Hastat, o Anciente, lhe pediu um Tendão de Dragão Azul Maduro. Se você encontrar esse tendão, vá falar com Hastat na Selva Maleva.",
    [7635] = "Stoma, o Anciente, lhe pediu um Tendão de Dragão Negro Maduro. Se você encontrar esse tendão, vá falar com Stoma na Selva Maleva.",
    [7636] = "Você precisa encontrar e destruir aqueles quatro corruptores demoníacos:$B$BSimone, a Sedutora.$B$BKlinfran, o Enlouquecido.$B$BSolenor, o Matador.$B$BArtórius, o Destruidor.$B$BDestrua aquelas criaturas e fale novamente com Vartrus, o Anciente, na Selva Maleva, trazendo as cabeças deles.$B$BConsulte a Casca Petrificada no seu inventário para ter pistas da localização deles.$B$BVocê TEM QUE completar a tarefa sozinh$Go:a;.",
    [7637] = "Viaje para Altaforja e obtenha o Incensório de Exorcismo do Sumo Sacerdote Rohan. Você precisará fazer uma doação de 150 moedas de ouro para obtê-lo.",
    [7638] = "Fale com o Lorde Grayson Quebrassombra no Distrito da Catedral de Ventobravo.",
    [7639] = "Leve o Incensório de Exorcismo para Lorde Grayson Quebrassombra no Distrito da Catedral de Ventobravo.",
    [7640] = "Use o Incensório de Exorcismo para expulsar os espíritos que atormentam a Várzea do Medo. Quando você tiver eliminado 25 Espíritos da Várzea do Medo, fale novamente com Lorde Grayson Quebrassombra no Distrito da Catedral de Ventobravo.",
    [7641] = "Fale com Grimand Elmore em Ventobravo no Distrito dos Anões de Ventobravo.",
    [7642] = "Leve 40 Runatramas, 6 Barras de Arcanita, 10 Lágrimas-de-arthas, 5 ampolas de Água Benta de Stratholme e 150 moedas de ouro para Grimand Elmore, no Distrito dos Anões de Ventobravo.",
    [7643] = "Obtenha uma ração de cavalo especial para alimentar o cavalo espiritual. Aparentemente, Judite Castanheira, que vive na Costa Sul, é a fornecedora da tal ração.$B$BEntre na masmorra de Gládio Cruel, em Feralas, e mate Gavíneo Lenhatorta. Isso libertará o Espírito Equino Antigo. Alimente-o com a ração de cavalo especial, o que acalmará o espírito. Finalmente, dê-lhe a Barda de Arcanita para que ele a abençoe.",
    [7644] = "Leve a Barda de Arcanita Abençoada para Lorde Grayson Quebrassombra no Distrito da Catedral de Ventobravo.",
    [7645] = "Obtenha 20 Biscoitos de Maná Enriquecido — o ingrediente chave para fazer Ração de Cavalo Enriquecida com Mana — para Judite Castanheira da Costa Sul, no Contraforte de Eira dos Montes. A Aurora Argêntea é conhecida como a única fornecedora dos biscoitos.$B$BVocê também precisa dar a ela 50 moedas de ouro para a apaziguar os ânimos dela.",
    [7646] = "Leve um Diamante Azerotiano e um Diamante Preto Límpido para Lorde Grayson Quebrassombra no Distrito da Catedral de Ventobravo.",
    [7647] = "Use o Cristal Divinatório no coração do porão do Grande Ossário, em Scolomântia. Isso invocará espíritos que você precisará julgar. A derrota dos espíritos evocará o Cavaleiro da Morte Noctilatrus. Derrote-o e reclame a alma perdida do corcel caído.$B$BEntregue a Alma Redimida do Corcel e a Barda Encantada Abençoada ao Corcel Caído de Noctilatrus.",
    [7648] = "Leve a Barda de Arcanita para Lorde Grayson Quebrassombra no Distrito da Catedral de Ventobravo para que ele a inspecione.",
    [7703] = "Encontre as Manoplas do Poder de Gordok e devolva-as para o Capitão Kebrapaw no Gládio Cruel.$B$BDe acordo com Kebrapaw, a \"história de ancião\" diz que Tortheldrin — um elfo \"medonho\" que se diz príncipe — roubou as manoplas de um dos reis Gordok.",
    [7761] = "Sem dúvida, um orc excepcionalmente burro. Parece que para acessar o Orbe de Comando é necessário ter a Marca de Drakkisath.$B$BA carta indica que o próprio General Drakkisath a guarda. Talvez você devesse investigar.",
    [7785] = "Examine o Casulo de Renascimento e entregue-o para o Grão-lorde Dimitriano.",
    [7786] = "Para libertar Trovejardus, o Perseguidor dos Ventos, da prisão, você deve entregar as metades direita e esquerda dos Grilhões do Perseguidor dos Ventos, 10 Barras de Elemêntio e a Essência do Senhor do Fogo para o Grão-lorde Dimitriano, em Silithus.",
    [7787] = "Entregue a Lâmina Latente Beijada pelo Vento para o Grão-lorde Dimitriano.",
    [7877] = "Volte ao Ateneu e encontre o Tesouro dos Shen'dralar. Resgate sua recompensa!",
    [8181] = "Fale com Yeh'kinya.",
    [8182] = "Fale com Molthor na Selva do Espinhaço.",
    [8323] = "O Eremita Ortell quer que você traga 10 Textos Codificados do Crepúsculo",
    [8410] = "Colete uma amostra de ar, fogo, terra e água para Bath'rah, o Vigia dos Ventos.",
    [8412] = "Leve as partes para Bath'rah, o Vigia dos Ventos, fazer o totem de espírito.",
    [8921] = "Leve para o Mux Zoamana, em Geringontzan, 1 Conversor Delicado de Arcanita, 4 Essências Eternas Maiores, 10 unidades de Óleo de Petrescama, 25 Cinzas Vulcânicas e 40 peças de ouro.",
    [8922] = "Leve o Recipiente Lacrado de Sangue para Mux Zoamana em Geringontzan, em Tanaris.",
    [8923] = "Leve o Recipiente de Peçonha Lacrado para Mux Zoamana em Geringontzan.",
    [8924] = "Use o Destilador Ectoplásmico perto de mortos-vivos incorpóreos para coletar 12 Ectoplasmas Chamuscados em Silithus, 12 Ectoplasmas Congelados em Hibérnia e 12 Ectoplasmas Estáveis nas Terras Pestilentas Orientais. Leve-os juntamente com o Destilador Ectoplásmico para Mux Zoamana em Geringontzan.",
    [8925] = "Encontre Bokk, Senhor do Magma, nas Estepes Ardentes, obtenha o Núcleo de Magma dele e leve-o para Mux Zoamana em Geringontzan.",
    [8928] = "Procure um diabrete em uma caverna na entrada da Garganta do Sussurro Sombrio, no sul de Hibérnia, compre um Bastão de Elemental Vil e fale novamente com Mux Zoamana em Geringontzan.",
    [8929] = "Use o Revelador Extradimensional de Fantasmas na entrada de Stratholme e fale com o fantasma de Anthion Harmon.",
    [8930] = "Use o Revelador Extradimensional de Fantasmas na entrada de Stratholme e fale com o fantasma de Anthion Harmon.",
    [8945] = "Entre em Stratholme e resgate Ysida Harmon do Barão Rivendare.",
    [8946] = "Leve o Medalhão de Ysida para Anthion Harmon nas Terras Pestilentas Orientais.",
    [8947] = "Leve 3 Barras de Ferro Negro, 20 Couros Encantados, 3 Lunatramas e 4 Pelegos Rústicos Curados para Anthion Harmon nas Terras Pestilentas Orientais.",
    [8948] = "Leve o Estandarte Incompleto da Provocação para Falrin Arboril na biblioteca do Gládio Cruel.",
    [8949] = "Colete 25 Colares de Guerra dos Ogros dos Ogros no Gládio Cruel ou no Pico da Rocha Negra e fale novamente com Falrin Arboril no Ateneu do Gládio Cruel.",
    [8950] = "Leve os seguintes materiais para Falrin Arboril no Gládio Cruel: 1 Essência de Espírito Zombeteiro, 4 Runas Negras e 8 Estilhaços Brilhantes Grandes.",
    [8960] = "Vá até a Montanha Rocha Negra e use o Revelador Extradimensional de Fantasmas para encontrar Bodley próximo ao Pico da Rocha Negra.",
    [8961] = "Colete a Incendicita de Incendius, a Brasa do Mirabrasa e a Cinza das Cinzas, além de um Braseiro Santificado, e fale novamente com Bodley na Montanha Rocha Negra.",
    [8962] = "Obtenha Restos Mortais Druídicos e os leve para Bodley na Montanha Rocha Negra.",
    [8963] = "Obtenha uma Relíquia do Vilarejo Brisastral e leve-a para Bodley na Montanha Rocha Negra.",
    [8964] = "Obtenha uma Espada Brilhante do Fanatismo e leve-a para Bodley na Montanha Rocha Negra.",
    [8965] = "Obtenha Cinzas de Alma Banida e leve-as para Bodley, dentro da Montanha Rocha Negra.",
    [8966] = "Use o Braseiro de Sinalização para evocar o espírito de Mor Casco Gris e então mate-o. Fale novamente com Bodley na Montanha Rocha Negra, com a Parte Esquerda do Amuleto do Lorde Valthalak e o Braseiro de Sinalização.",
    [8967] = "Use o Braseiro de Sinalização para evocar o espírito de Isalien e então mate-o. Fale novamente com Bodley na Montanha Rocha Negra, com a Parte Esquerda do Amuleto do Lorde Valthalak restaurado e o Braseiro de Sinalização.",
    [8968] = "Use o Braseiro de Sinalização para evocar os espíritos de Jil e Soeiro e então mate os dois. Fale novamente com Bodley na Montanha Rocha Negra, com a Parte Esquerda do Amuleto do Lorde Valthalak e o Braseiro de Sinalização.",
    [8969] = "Use o Braseiro de Sinalização para evocar o espírito de Kormok e então mate-o. Fale novamente com Bodley, na Montanha Rocha Negra, com a Parte Esquerda do Amuleto do Lorde Valthalak e o Braseiro de Sinalização.",
    [8970] = "Colete 20 Algassangues das nagas Strashaz e fale novamente com Bodley na Montanha Rocha Negra.",
    [8977] = "Leve o Revelador Extradimensional de Fantasmas para Deliana, em Altaforja.",
    [8978] = "Reporte-se a Mokvar, em Orgrimmar, com o Revelador Extradimensional de Fantasmas.",
    [8985] = "Obtenha uma Relíquia do Vilarejo Brisastral e leve-a para Bodley na Montanha Rocha Negra.",
    [8986] = "Obtenha Restos Mortais Druídicos e os leve para Bodley na Montanha Rocha Negra.",
    [8987] = "Obtenha uma Espada Brilhante do Fanatismo e leve-a para Bodley na Montanha Rocha Negra.",
